const legacyRender=render, legacyEntryCover=drawEntryCover, legacyCategoryIcon=categoryIcon, legacySaveRecord=saveRecord;
const navigation=[];
let categoryType='expense',entryCategoryId='daily-0',categoryScheme='日常通用',categoryParent='daily-0',categoryPending='daily-0',categoryMode='entry',entryAccountId=null,selectedAccountId=null,accountDraft=null,accountReturn='assets',hideAssets=false,operation=null;
const accountKey='xiaohei-figma-accounts-v1';
