go=function(name){if(name!==scene)navigation.push(scene);previous=scene;scene=name;render()};
back=function(){scene=navigation.pop()||'home';render()};
function returnEntry(){while(navigation.length&&navigation.at(-1)!=='entry')navigation.pop();if(navigation.at(-1)==='entry')navigation.pop();scene='entry';render()}
categoryIcon=function(record){if(record.actionIndex!==undefined)return actionIcon(record.actionIndex);const named=String(record.category||'').split('-').at(-1),c=(named==='投资'?incomeCategories.find(c=>c.id==='income-invest'):null)||allCategories().find(c=>c.id===record.categoryId&&(c.name===named||record.operation))||allCategories().find(c=>c.name===String(record.category).split('-').at(-1));return c?sprite(c.art,30):legacyCategoryIcon(record)};
openEntry=function(){operation=null;entryType='expense';entryCategory='餐饮';entryCategoryId='daily-0';categoryPending=entryCategoryId;entryCategoryChosen=false;entryNumber='';entryMemo='';entryDate=today();const a=accounts.find(a=>a.default);entryAccountId=a?.id||null;entryAccount=a?accountName(a):'账户';go('entry')};
