drawEntryCover=function(){legacyEntryCover();screen.querySelectorAll('.hit').forEach(b=>{if([...categoryNames,'支出','收入','笔记模式','账户','默认账本','日期','计入收支'].includes(b.getAttribute('aria-label')))b.remove()});screen.querySelectorAll('.income-pane,.selected-category,.entry-catalog,.entry-meta').forEach(n=>n.remove());const pane=document.createElement('div');pane.className='entry-catalog';const list=entryType==='income'?incomeCategories.slice(0,5):dailyCategories.slice(0,5);pane.innerHTML='<div class="entry-type"><button data-type="expense" class="'+(entryType==='expense'?'active':'')+'">支出</button><span></span><button data-type="income" class="'+(entryType==='income'?'active':'')+'">收入</button><button class="note-switch">⇄ 笔记模式</button></div><div class="entry-category-grid">'+list.map(c=>'<button data-category="'+c.id+'" class="'+(entryCategoryChosen&&entryCategoryId===c.id?'chosen':'')+'"><i>'+sprite(c.art,32)+'</i><span>'+esc(c.name)+'</span><em>⌄</em></button>').join('')+'<button class="all-categories" aria-label="全部分类">全部<br>分类 ›</button></div>';screen.appendChild(pane);pane.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>selectEntryType(b.dataset.type));pane.querySelector('.note-switch').onclick=()=>go('note');pane.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{categoryParent=b.dataset.category;categoryPending=entryCategoryId;categoryType=entryType;categoryMode='entry';go('category')});pane.querySelector('.all-categories').onclick=()=>{categoryType=entryType;categoryMode='entry';categoryParent='daily-0';categoryPending=entryCategoryId;go('category')};const meta=document.createElement('div');meta.className='entry-meta';const current=allCategories().find(c=>c.id===entryCategoryId);meta.innerHTML='<button class="account-chip">'+esc(entryAccount)+' ⌄</button><button class="book-chip">默认账本 ⌄</button><button class="date-chip">'+esc(entryDate.slice(5))+' ⌄</button><button class="chosen-chip">'+(current?sprite(current.art,16):'')+esc(entryCategory)+' ⌄</button>';screen.appendChild(meta);meta.querySelector('.account-chip').onclick=()=>{accountReturn='entry';go('accounts')};meta.querySelector('.book-chip').onclick=()=>go('ledgers');meta.querySelector('.date-chip').onclick=()=>{const d=screen.querySelector('#date-picker');d.showPicker?.()};meta.querySelector('.chosen-chip').onclick=()=>{categoryType=entryType;categoryMode='entry';categoryPending=entryCategoryId;go('category')};const date=screen.querySelector('#date-picker');date.onchange=e=>{entryDate=e.target.value;drawEntryCover()}};
saveRecord=function(){const value=numericValue();if(!Number.isFinite(value)||value<=0){message('请输入有效金额');return}const d=new Date(),a=accounts.find(a=>a.id===entryAccountId);const r={id:'record-'+Date.now(),type:entryType,category:entryCategory,categoryId:entryCategoryId,amount:Math.round(value*100)/100,note:entryMemo,account:a?accountName(a):'未选择账户',accountId:a?.id,date:entryDate,time:d.toTimeString().slice(0,5)};added.unshift(r);localStorage.setItem(storeKey,JSON.stringify(added));if(a){const delta=entryType==='income'?r.amount:-r.amount;a.balance=Math.round((a.balance+(getType(a).debt?-delta:delta))*100)/100;persistAccounts()}scene='home';navigation.length=0;render();message('记录成功')};
function categoryButton(c,expand=false){return '<button class="category-option '+(categoryPending===c.id?'chosen':'')+'" data-cat="'+c.id+'"><i>'+sprite(c.art,35)+'</i><span>'+esc(c.name)+'</span>'+(expand?'<em class="'+(categoryParent===c.id?'expanded':'')+'">'+(categoryParent===c.id?'⌃':'⌄')+'</em>':'')+'</button>'}
categoryExpanded=function(){const mother=categoryScheme==='母婴相关';const list=mother?maternalCategories.filter(c=>c.type===categoryType):categoryType==='expense'?[...dailyCategories,...customCategories.filter(c=>c.type==='expense')]:[...incomeCategories,...customCategories.filter(c=>c.type==='income')];let parent=allCategories().find(c=>c.id===categoryParent);let children=!mother&&categoryType==='expense'?(categoryParent==='daily-0'?foodChildren:categoryParent==='daily-maternal'?maternalCategories.filter(c=>c.type==='expense'):categoryParent==='daily-2'?foodChildren.filter(c=>['甜品','零食'].includes(c.name)):categoryParent==='daily-3'?foodChildren.filter(c=>c.name==='水果'):categoryParent==='daily-1'?foodChildren.filter(c=>['酒水','奶茶','咖啡','饮料'].includes(c.name)):categoryParent==='daily-4'?foodChildren.filter(c=>c.name==='做饭食材'):[]):[];screen.innerHTML='<div class="category-backdrop"></div><section class="category-sheet"><button class="sheet-handle" aria-label="关闭分类"></button><div class="scheme-title"><select aria-label="分类方案"><option'+(!mother?' selected':'')+'>日常通用</option><option'+(mother?' selected':'')+'>母婴相关</option></select></div><div class="category-tabs"><button data-tab="expense" class="'+(categoryType==='expense'?'active':'')+'">支出</button><button data-tab="income" class="'+(categoryType==='income'?'active':'')+'">收入</button></div><div class="category-scroll"><div class="category-grid">'+list.slice(0,5).map(c=>categoryButton(c,!mother&&categoryType==='expense')).join('')+'</div>'+(children.length?'<div class="category-children"><div class="category-grid">'+children.map(c=>categoryButton(c)).join('')+'</div></div>':'')+'<div class="category-grid category-rest">'+list.slice(5).map(c=>categoryButton(c,!mother&&categoryType==='expense')).join('')+'</div></div><div class="category-footer"><button class="pill-primary" id="confirm-category">确定</button></div></section>';screen.querySelector('.sheet-handle').onclick=()=>categoryMode==='manage'?back():returnEntry();screen.querySelector('select').onchange=e=>{categoryScheme=e.target.value;categoryParent='';categoryExpanded()};screen.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{categoryType=b.dataset.tab;categoryParent='';categoryPending='';categoryExpanded()});screen.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{categoryPending=b.dataset.cat;if(dailyCategories.some(c=>c.id===b.dataset.cat))categoryParent=categoryParent===b.dataset.cat?'':b.dataset.cat;categoryExpanded()});screen.querySelector('#confirm-category').onclick=()=>{const c=allCategories().find(c=>c.id===categoryPending);if(!c){message('请选择分类');return}entryType=categoryType;entryCategoryId=c.id;entryCategory=c.parent?c.parent+'-'+c.name:c.name;entryCategoryChosen=true;categoryMode==='manage'?back():returnEntry()}};
function categoriesPage(){page('分类管理','<div class="scheme-row"><b>'+esc(categoryScheme)+'</b><button class="text-button" id="preview-categories">预览分类 ›</button></div><div class="category-tabs"><button class="active" data-mode="expense">支出</button><button data-mode="income">收入</button></div><div id="management-list"></div><button class="pill-primary" id="add-category">添加分类</button>');const list=()=>{const items=categoryScheme==='母婴相关'?maternalCategories.filter(c=>c.type===entryType):entryType==='expense'?[...dailyCategories,...foodChildren,...customCategories.filter(c=>c.type===entryType)]:[...incomeCategories,...customCategories.filter(c=>c.type===entryType)];screen.querySelector('#management-list').innerHTML=items.map(c=>'<div class="management-row">'+sprite(c.art,32)+'<span>'+esc(c.parent?c.parent+' / '+c.name:c.name)+'</span></div>').join('')};entryType='expense';list();screen.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{entryType=b.dataset.mode;screen.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));list()});screen.querySelector('#preview-categories').onclick=()=>{categoryType=entryType;categoryMode='manage';go('category')};screen.querySelector('#add-category').onclick=()=>go('addCategory')}
function addCategoryPage(){page('添加分类','<div class="form-card"><label class="form-row"><span>分类名称</span><input id="new-category-name" maxlength="12" placeholder="请输入分类名称"></label><label class="form-row"><span>收支类型</span><select id="new-category-type"><option value="expense">支出</option><option value="income">收入</option></select></label></div><h3>选择图标</h3><p class="subtle small">母婴相关</p><div class="category-grid" id="icon-options">'+maternalCategories.map(c=>categoryButton(c)).join('')+'</div><button class="pill-primary" id="save-category">保存</button>');let icon=maternalCategories[0];screen.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{icon=maternalCategories.find(c=>c.id===b.dataset.cat);screen.querySelectorAll('[data-cat]').forEach(x=>x.classList.toggle('chosen',x===b))});screen.querySelector('#save-category').onclick=()=>{const name=screen.querySelector('#new-category-name').value.trim(),type=screen.querySelector('#new-category-type').value;if(!name){message('请输入分类名称');return}if(allCategories().some(c=>c.name===name&&c.type===type)){message('该分类已存在');return}customCategories.push({id:'custom-'+Date.now(),name,type,art:icon.art});localStorage.setItem('xiaohei-custom-categories',JSON.stringify(customCategories));back();message('分类已添加')}}
