function assetsPage(){const included=accounts.filter(a=>a.include!==false),assets=included.filter(a=>!getType(a).debt).reduce((s,a)=>s+a.balance,0),debt=included.filter(a=>getType(a).debt).reduce((s,a)=>s+a.balance,0);page('资产','<section class="asset-summary"><div>净资产 <button id="hide-assets" class="text-button" aria-label="显示或隐藏资产">'+(hideAssets?'◉':'◎')+'</button></div><div class="asset-total">'+(hideAssets?'****':cash(assets-debt))+'</div><div class="asset-columns"><span>资产<b>'+(hideAssets?'****':cash(assets))+'</b></span><span>负债<b>'+(hideAssets?'****':cash(debt))+'</b></span></div><div class="debt-rate">资产负债率 <b>'+(hideAssets?'****':(assets?debt/assets*100:0).toFixed(2)+'%')+'</b></div></section><div class="asset-title"><b>资产账户</b><button class="text-button" id="add-account">＋ 添加账户</button></div>'+accountGroups.map(g=>'<section class="asset-group"><h3>'+g.name+'</h3><div class="account-card">'+(accounts.filter(a=>getType(a).group===g.id).map(accountRow).join('')||'<button class="empty-account" data-add-group="'+g.id+'">＋ 添加'+g.name.split('(')[0]+'</button>')+'</div></section>').join(''));screen.querySelector('.page').classList.add('assets-page');screen.querySelector('.page-head span').innerHTML='资产 <span class="inactive-tab">物品</span>';screen.querySelector('.inactive-tab').onclick=()=>go('items');screen.querySelector('#hide-assets').onclick=()=>{hideAssets=!hideAssets;assetsPage()};screen.querySelector('#add-account').onclick=()=>{accountReturn='assets';go('accountTypes')};screen.querySelectorAll('[data-add-group]').forEach(b=>b.onclick=()=>{accountReturn='assets';go('accountTypes')});screen.querySelectorAll('[data-account-id]').forEach(b=>b.onclick=()=>{selectedAccountId=b.dataset.accountId;go('accountDetail')})}
