const field=(name,id,value='',placeholder='',type='text')=>'<label class="form-row"><span>'+name+'</span><input id="'+id+'" type="'+type+'" value="'+esc(value)+'" placeholder="'+placeholder+'"></label>';
function accountForm(){const t=getType(accountDraft),bank=t.name==='储蓄卡'||t.name==='信用卡';page(accountDraft.id?'编辑账户':'添加账户','<div class="chosen-type">'+accountIcon(t)+'<span>'+t.name+'</span></div><form id="account-form">'+(bank?'<div class="form-card"><label class="form-row"><span>银行名称</span><select id="account-bank"><option value="">选择银行(必选)</option>'+['交通银行','招商银行','中国工商银行','中国建设银行','中国农业银行','中国银行','邮政储蓄银行','浦发银行','中信银行','其他银行'].map(n=>'<option'+(accountDraft.bank===n?' selected':'')+'>'+n+'</option>').join('')+'</select></label></div>':'')+'<div class="balance-card"><span>'+(t.debt?'当前欠款':'当前余额')+'</span><label>¥<input aria-label="当前余额" id="account-balance" type="number" step="0.01" value="'+(accountDraft.balance||0)+'"></label></div><div class="form-card">'+field('账户名称','account-name',accountDraft.name||'','请输入账户名称')+(bank?field('卡号后四位','account-digits',accountDraft.digits||'','请输入后四位'):'')+(t.group==='lend'?field(t.debt?'债权人':'债务人','account-person',accountDraft.person||'','请输入姓名'):'')+(t.group==='credit'?field('总额度','account-limit',accountDraft.limit||'','请输入额度','number')+field('出账日','account-bill',accountDraft.billDay||'','每月几号','number')+field('还款日','account-due',accountDraft.dueDay||'','每月几号','number'):'')+field('备注','account-note',accountDraft.note||'','请输入备注')+'</div><div class="form-card"><label class="form-row">计入总资产<input class="switch" id="account-include" type="checkbox" '+(accountDraft.include!==false?'checked':'')+'></label><label class="form-row">设为默认收支账户<input class="switch" id="account-default" type="checkbox" '+(accountDraft.default?'checked':'')+'></label></div><button class="pill-primary" type="submit">保存</button></form>');screen.querySelector('.page').classList.add('soft-page');screen.querySelector('#account-form').onsubmit=e=>{e.preventDefault();const value=id=>screen.querySelector('#'+id)?.value.trim()||'',balance=Number(value('account-balance')),digits=value('account-digits'),bankName=value('account-bank');if(bank&&!bankName){message('请选择银行');return}if(!Number.isFinite(balance)){message('请输入有效余额');return}if(digits&&!/^\d{4}$/.test(digits)){message('卡号后四位请输入4位数字');return}for(const id of ['account-bill','account-due'])if(value(id)&&(!/^\d+$/.test(value(id))||Number(value(id))<1||Number(value(id))>31)){message('日期请输入1至31');return}const a={...accountDraft,id:accountDraft.id||'account-'+Date.now(),name:value('account-name')||bankName||t.name,bank:bankName,digits,balance,person:value('account-person'),limit:Number(value('account-limit'))||0,billDay:value('account-bill'),dueDay:value('account-due'),note:value('account-note'),include:screen.querySelector('#account-include').checked,default:screen.querySelector('#account-default').checked};if(a.default)accounts.forEach(a=>a.default=false);const i=accounts.findIndex(x=>x.id===a.id);if(i<0)accounts.push(a);else accounts[i]=a;persistAccounts();if(accountReturn==='operation'&&operation){operation[operation.selecting]=a.id;while(navigation.length&&navigation.at(-1)!=='assetOperation')navigation.pop();back()}else if(accountReturn==='entry'){entryAccountId=a.id;entryAccount=accountName(a);returnEntry()}else{navigation.length=0;scene='assets';render()}message('账户已保存')}}
function accountSelector(){page('选择账户',accountGroups.map(g=>{const items=accounts.filter(a=>getType(a).group===g.id&&(!operation||a.id!==(operation.selecting==='from'?operation.to:operation.from)));return items.length?'<h3>'+g.name+'</h3><div class="account-card">'+items.map(accountRow).join('')+'</div>':''}).join('')+'<button class="pill-primary" id="selector-add">＋ 添加账户</button>');screen.querySelector('.page').classList.add('soft-page');screen.querySelectorAll('[data-account-id]').forEach(b=>b.onclick=()=>{const a=accounts.find(a=>a.id===b.dataset.accountId);if(operation){operation[operation.selecting]=a.id;back()}else{entryAccountId=a.id;entryAccount=accountName(a);returnEntry()}});screen.querySelector('#selector-add').onclick=()=>{accountReturn=operation?'operation':'entry';go('accountTypes')}}
function accountDetailPage(){const a=accounts.find(a=>a.id===selectedAccountId);if(!a){scene='assets';render();return}const t=getType(a),actions=t.debt?['记账','转账','还款']:t.group==='recharge'?['记账','充值']:['记账','转账'];page(t.debt?'负债':'资产','<section class="balance-card detail-balance"><div class="account-heading">'+accountIcon(t)+'<b>'+esc(accountName(a))+'</b><button class="text-button" id="edit-account">编辑</button></div><small>'+(t.debt?'欠款':'余额')+'</small><div class="metric">'+cash(a.balance)+' <button id="adjust-account" class="text-button" aria-label="调整余额">✎</button></div><div class="account-actions">'+actions.map(x=>'<button data-action="'+x+'">'+x+'</button>').join('')+'</div></section><div class="category-tabs"><button class="active" id="account-records">资产明细</button><button id="account-notes">账单明细</button></div><div id="account-history"></div>');screen.querySelector('#edit-account').onclick=()=>{accountDraft={...a};accountReturn='assets';go('accountForm')};screen.querySelector('#adjust-account').onclick=()=>startOperation('手动调整',a);screen.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{if(b.dataset.action==='记账'){openEntry();entryAccountId=a.id;entryAccount=accountName(a);render()}else startOperation(b.dataset.action,a)});const history=onlyBills=>{const records=added.filter(r=>(r.accountId===a.id||r.toAccountId===a.id)&&(!onlyBills||!r.operation));screen.querySelector('#account-history').innerHTML=records.map(r=>'<button class="asset-record" data-record="'+r.id+'"><small>'+esc(r.date)+' '+esc(r.time)+'</small><div>'+categoryPill(r)+'<strong class="'+r.type+'">'+(r.type==='income'?'+':'−')+cash(r.amount)+'</strong></div><p>'+esc(r.note||r.account||'')+'</p></button>').join('')||'<div class="empty">暂无记录</div>';screen.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>detail(added.find(r=>r.id===b.dataset.record)))};history(false);screen.querySelectorAll('.category-tabs button').forEach((b,i)=>b.onclick=()=>{screen.querySelectorAll('.category-tabs button').forEach(x=>x.classList.toggle('active',x===b));history(i===1)})}
function startOperation(kind,a){operation={kind,from:kind==='充值'||kind==='还款'?null:a.id,to:kind==='充值'||kind==='还款'?a.id:null,amount:kind==='手动调整'?a.balance:'',fee:'',date:today(),note:''};go('assetOperation')}
function operationPage(){const o=operation;if(!o){back();return}const name=id=>accounts.find(a=>a.id===id),button=(key,label)=>'<button class="form-row account-select" data-select="'+key+'"><span>'+label+'</span><span>'+esc(name(o[key])?accountName(name(o[key])):'请选择账户')+' ›</span></button>';page(o.kind,'<form id="operation-form"><label class="balance-card operation-amount"><span>'+(o.kind==='手动调整'?'调整后的余额':o.kind+'金额')+'</span><span>¥ <input type="number" step="0.01" min="0" id="operation-amount" aria-label="金额" value="'+o.amount+'" placeholder="0.00"></span></label><div class="form-card">'+(o.kind==='手动调整'?'':button('from','扣款账户')+button('to','入款账户')+(o.kind==='转账'?field('手续费','operation-fee',o.fee,'请输入金额','number'):''))+field('日期','operation-date',o.date,'','date')+field('备注','operation-note',o.note,'请输入备注')+'</div><button class="pill-primary bottom-submit" type="submit">完成</button></form>');const capture=()=>{o.amount=screen.querySelector('#operation-amount').value;o.date=screen.querySelector('#operation-date').value;o.note=screen.querySelector('#operation-note').value;o.fee=screen.querySelector('#operation-fee')?.value||0};screen.querySelectorAll('[data-select]').forEach(b=>b.onclick=e=>{e.preventDefault();capture();o.selecting=b.dataset.select;go('accounts')});screen.querySelector('#operation-form').onsubmit=e=>{e.preventDefault();capture();const amount=Number(o.amount),fee=Number(o.fee||0),from=name(o.from),to=name(o.to);if(!Number.isFinite(amount)||amount<0||!Number.isFinite(fee)||fee<0||!o.date){message('请填写有效金额和日期');return}if(o.kind!=='手动调整'&&(!from||!to||amount<=0)){message('请选择账户并填写金额');return}if(o.kind!=='手动调整'&&!getType(from).debt&&from.balance<amount+fee){message('扣款账户余额不足');return}if(o.kind==='还款'&&getType(to).debt&&amount>to.balance){message('还款金额不能超过欠款');return}const d=new Date(),a=accounts.find(a=>a.id===selectedAccountId),before=a.balance;let r;if(o.kind==='手动调整'){a.balance=amount;r={type:amount>before?'income':'expense',amount:Math.abs(amount-before),category:'手动调整',actionIndex:amount>before?5:4,accountId:a.id,account:accountName(a),note:before+'调整至'+amount}}else{from.balance+=(getType(from).debt?1:-1)*(amount+fee);to.balance+=(getType(to).debt?-1:1)*amount;r={type:'expense',amount,category:o.kind,actionIndex:o.kind==='还款'?6:o.kind==='充值'?2:0,accountId:from.id,toAccountId:to.id,account:accountName(from)+' → '+accountName(to),note:o.note}}accounts.forEach(a=>a.balance=Math.round(a.balance*100)/100);added.unshift({...r,id:'operation-'+Date.now(),operation:true,date:o.date,time:d.toTimeString().slice(0,5),note:o.note||r.note});persistAccounts();localStorage.setItem(storeKey,JSON.stringify(added));operation=null;navigation.length=0;scene='accountDetail';render();message('已完成'+o.kind)}}
render=function(){const pages={assets:assetsPage,accountTypes:accountTypesPage,accountForm,accounts:accountSelector,accountDetail:accountDetailPage,assetOperation:operationPage,categories:categoriesPage,addCategory:addCategoryPage};device.classList.toggle('drawer-fit',scene==='drawer');if(pages[scene])pages[scene]();else legacyRender()};
render();
// Additional fields present in the latest credit account annotation.
const baseAccountForm=accountForm;
accountForm=function(){baseAccountForm();const t=getType(accountDraft),form=screen.querySelector('#account-form');if(t.group==='credit'){const credit=screen.querySelector('#account-limit').closest('label');credit.querySelector('span').textContent='信用额度';const balance=screen.querySelector('.balance-card');balance.innerHTML='<div class="form-row"><span>信用额度</span><input id="account-limit" type="number" step="0.01" value="'+(accountDraft.limit||'')+'" placeholder="请输入信用额度"></div><div class="form-row"><span>欠款</span><input id="account-balance" aria-label="欠款" type="number" step="0.01" value="'+(accountDraft.balance||0)+'"></div><div class="form-row"><span>可用额度</span><span id="available-credit"></span></div>';credit.remove();const update=()=>{const limit=Number(screen.querySelector('#account-limit').value),debt=Number(screen.querySelector('#account-balance').value);screen.querySelector('#available-credit').textContent=limit?cash(limit-debt):'输入信用额度和欠款自动计算'};screen.querySelector('#account-limit').oninput=update;screen.querySelector('#account-balance').oninput=update;update();const note=screen.querySelector('#account-note').closest('label'),bill=screen.querySelector('#account-bill').closest('label'),due=screen.querySelector('#account-due').closest('label');note.after(bill,due);due.insertAdjacentHTML('afterend',field('每期还款金额','account-installment',accountDraft.installment||'','请输入每期还款金额','number'));const submit=form.onsubmit;form.onsubmit=e=>{accountDraft.installment=Number(screen.querySelector('#account-installment').value)||0;submit(e)}}const chosen=screen.querySelector('.chosen-type'),bank=screen.querySelector('#account-bank')?.closest('.form-card');if(bank){chosen.appendChild(bank);chosen.classList.add('has-bank')}};
const baseBack=back;
back=function(){if(scene==='assetOperation')operation=null;baseBack()};
